/**  Safety classification, ordered from least to most dangerous to remove. */
export type SafetyClass = 
/**  Proven reproducible cache with no persistent user data. */
"safe" | 
/**  Reinstall/rebuild required, but no original user data is lost. */
"regenerate" | 
/**  User data, costly environment, or insufficient evidence. Manual decision. */
"review" | 
/**  Protected data. Never selectable, never deletable. */
"keep";

export type ScanEvent = ScanEvent_Serialize | ScanEvent_Deserialize;

export type ScanEvent_Deserialize = { type: "started"; scanId: string } | { type: "candidates"; items: CleanupItem_Deserialize[] } | { type: "measured"; updates: MeasurementUpdate_Deserialize[] } | { type: "progress"; progress: ScanProgress_Deserialize } | { type: "warning"; code: string; path?: string | null; severity?: ScanNoticeSeverity; root?: string | null } | { type: "completed"; summary: ScanSummary_Deserialize } | 
/**
 *  A scan that finished because a limit or the timeout stopped it. This is
 *  deliberately separate from `Cancelled`: the user did not cancel, but the
 *  result is incomplete and must be presented as partial.
 */
{ type: "partial"; summary: ScanSummary_Deserialize } | { type: "cancelled"; summary: ScanSummary_Deserialize } | { type: "failed"; error: AppError };

export type ScanEvent_Serialize = { type: "started"; scanId: string } | { type: "candidates"; items: CleanupItem_Serialize[] } | { type: "measured"; updates: MeasurementUpdate_Serialize[] } | { type: "progress"; progress: ScanProgress_Serialize } | { type: "warning"; code: string; path: string | null; severity: ScanNoticeSeverity; root: string | null } | { type: "completed"; summary: ScanSummary_Serialize } | 
/**
 *  A scan that finished because a limit or the timeout stopped it. This is
 *  deliberately separate from `Cancelled`: the user did not cancel, but the
 *  result is incomplete and must be presented as partial.
 */
{ type: "partial"; summary: ScanSummary_Serialize } | { type: "cancelled"; summary: ScanSummary_Serialize } | { type: "failed"; error: AppError };

export type ScanNoticeSeverity = 
/**  Expected skip; no user action needed. */
"info" | 
/**
 *  A location inside the selected scope could not be read: results may be
 *  missing entries.
 */
"warning" | 
/**  The scan itself was blocked (root unreadable, drive failure). */
"error";

